package com.abhishek.hotelbooking.service.impl; import com.abhishek.hotelbooking.dto.booking.*; import com.abhishek.hotelbooking.entity.*; import com.abhishek.hotelbooking.enums.*; import com.abhishek.hotelbooking.exception.*; import com.abhishek.hotelbooking.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.time.temporal.ChronoUnit; import java.util.*;
@Service public class BookingService { private final BookingRepository bookings; private final RoomRepository rooms; private final UserRepository users; public BookingService(BookingRepository bookings,RoomRepository rooms,UserRepository users){this.bookings=bookings;this.rooms=rooms;this.users=users;} @Transactional public BookingResponse create(String email,BookingRequest r){if(!r.checkIn().isBefore(r.checkOut()))throw new ConflictException("checkIn must be before checkOut"); Room room=rooms.findById(r.roomId()).orElseThrow(()->new ResourceNotFoundException("Room not found")); if(bookings.existsOverlap(room.getId(),r.checkIn(),r.checkOut()))throw new ConflictException("Room is already booked for the selected dates"); long nights=ChronoUnit.DAYS.between(r.checkIn(),r.checkOut()); User u=users.findByEmail(email).orElseThrow(()->new ResourceNotFoundException("User not found")); Booking b=bookings.save(Booking.builder().user(u).room(room).checkIn(r.checkIn()).checkOut(r.checkOut()).totalAmount(room.getPricePerNight().multiply(BigDecimal.valueOf(nights))).status(BookingStatus.CONFIRMED).paymentStatus(PaymentStatus.PENDING).build()); return map(b);} public List<BookingResponse> mine(String email){Long id=users.findByEmail(email).orElseThrow(()->new ResourceNotFoundException("User not found")).getId();return bookings.findByUserIdOrderByIdDesc(id).stream().map(this::map).toList();} @Transactional public BookingResponse cancel(String email,Long id){Booking b=bookings.findById(id).orElseThrow(()->new ResourceNotFoundException("Booking not found")); if(!b.getUser().getEmail().equals(email))throw new ConflictException("You can cancel only your own booking"); if(b.getStatus()==BookingStatus.CANCELLED)throw new ConflictException("Booking already cancelled"); b.setStatus(BookingStatus.CANCELLED); if(b.getPaymentStatus()==PaymentStatus.PAID)b.setPaymentStatus(PaymentStatus.REFUNDED); return map(b);} public Booking get(Long id){return bookings.findById(id).orElseThrow(()->new ResourceNotFoundException("Booking not found"));} public List<BookingResponse> all(){return bookings.findAll().stream().map(this::map).toList();} @Transactional public BookingResponse payment(Long id,PaymentStatus status){Booking b=get(id);b.setPaymentStatus(status);return map(b);} private BookingResponse map(Booking b){return new BookingResponse(b.getId(),b.getRoom().getId(),b.getRoom().getRoomNumber(),b.getCheckIn(),b.getCheckOut(),b.getTotalAmount(),b.getStatus().name(),b.getPaymentStatus().name());} }